\label{lem:edge-potential}
	\label{thm:full-gradient}
	\label{thm:rotation}
	The potential $\mathcal V$ is independent of the edge orientation and
	determined up to an additive constant.  Moreover:
	\begin{enumerate}[label=\textup{(\roman*)}]
		\item The network map is a gradient step for $\mathcal V$:
		\begin{equation}
			\label{eq:full-gradient-components}
			\nabla\Psi(z)=-A\mathbf g(z),\qquad
			\nabla\mathcal V(\theta)=-BA\mathbf g(B^T\theta),
		\end{equation}
		\begin{equation}
			\label{eq:full-gradient-step}
			\widetilde F_h(\theta)=\theta-h\nabla\mathcal V(\theta).
		\end{equation}
		\item For every $\alpha\in\mathbb R$,
		\begin{equation}
			\label{eq:F-rotation}
			\mathcal V(\theta+\alpha\mathbf 1)=\mathcal V(\theta),\qquad
			\widetilde F_h(\theta+\alpha\mathbf 1)=\widetilde F_h(\theta)+\alpha\mathbf 1 .
		\end{equation}
		\item $\mathbf 1^T\nabla\mathcal V(\theta)=0$, and the lifted map preserves
		the phase sum:
		\begin{equation}
			\label{eq:sum-conserved}
			\mathbf 1^T\widetilde F_h(\theta)=\mathbf 1^T\theta .
		\end{equation}
	\end{enumerate}
	In particular, $F_h$ descends to the $N$-dimensional quotient
	$\mathbb T_P^{N+1}/\mathbb T_P\simeq\mathbb T_P^N$ by common-phase shifts.

\label{thm:inherited-potential}
	\label{thm:reduced-gradient}
	There is a unique smooth \(V:\mathbb T_P^N\to\mathbb R\) satisfying
	\(\mathcal V=V\circ Q\). It is given by
	\begin{equation}
		\label{eq:reduced-potential}
		V(x)=\Psi(Cx),\qquad \nabla V(x)=-C^TA\mathbf g(Cx).
	\end{equation}
	The induced map \(\bar F_h:\mathbb T_P^N\to\mathbb T_P^N\) is
	\begin{equation}
		\label{eq:reduced-gradient-map}
		\bar F_h(x)=x-hM\nabla V(x)
		=x-h\operatorname{grad}_{M^{-1}}V(x),
		\qquad \operatorname{grad}_{M^{-1}}V=M\nabla V.
	\end{equation}

By \eqref{eq:F-rotation}, \(\mathcal V\) is constant on each fibre of
	\(Q\); evaluation at \(Sx\) gives the unique factor \(V(x)=\Psi(Cx)\).
	Differentiation gives its gradient and
	\begin{equation}
		\label{eq:chain-gradient}
		\nabla_\theta\mathcal V(\theta)=Q^T\nabla V(Q\theta).
	\end{equation}
	Apply \(Q\) to \eqref{eq:full-gradient-step} and use \(QQ^T=M\).
	The metric \eqref{eq:metric} then gives the stated Riemannian gradient.

\label{thm:Hessian-bound}
	For every \(\theta\in\mathbb T_P^{N+1}\) and \(v\in\mathbb R^{N+1}\),
	\begin{equation}
		\label{eq:Hessian-quadratic}
		|v^TD^2\mathcal V(\theta)v|
		\le v^TL_\beta v\le\Lambda\|v\|^2,
		\qquad \|D^2\mathcal V(\theta)\|_2\le\Lambda.
	\end{equation}

With \(\Gamma(\theta)=\operatorname{diag}
	(a_eg_e'((B^T\theta)_e))\), differentiation gives
	\begin{equation}
		\label{eq:Hessian-edge-form}
		D^2\mathcal V(\theta)=-B\Gamma(\theta)B^T.
	\end{equation}
	Thus
	\[
	|v^TD^2\mathcal V(\theta)v|
	\le\sum_e\beta_e(b_e^Tv)^2=v^TL_\beta v
	\le\Lambda\|v\|^2,
	\]
	and symmetry gives the norm bound.

\label{thm:finite-estimates}
	\label{thm:full-Lyapunov}
	\label{thm:reduced-Lyapunov}
	\label{thm:diffeomorphism}
	For \(0<h<2/\Lambda\), let \(c_h=h(1-h\Lambda/2)>0\). Then
	\begin{equation}
		\label{eq:reduced-descent}
		\begin{aligned}
			\mathcal V(F_h(\theta))
			&\le\mathcal V(\theta)-c_h\|\nabla\mathcal V(\theta)\|^2,\\
			V(\bar F_h(x))
			&\le V(x)-c_h\nabla V(x)^TM\nabla V(x),
		\end{aligned}
	\end{equation}
	so both potentials decrease strictly away from their critical sets.
	If \(0<h<1/\Lambda\), then \(F_h\) and \(\bar F_h\) are smooth global
	diffeomorphisms.

\label{thm:fixed-critical}
	\label{cor:no-periodic}
	\label{thm:approach-critical}
	\label{thm:finite-convergence}
	Let \(0<h<2/\Lambda\). Then
	\begin{equation}
		\label{eq:fixed-critical}
		\operatorname{Fix}(\bar F_h)=\operatorname{Crit}(V),
	\end{equation}
	and every periodic orbit of \(\bar F_h\) is fixed. Every forward orbit
	\(x_{n+1}=\bar F_h(x_n)\) satisfies
	\begin{equation}
		\label{eq:distance-critical}
		\nabla V(x_n)\to0,\qquad
		\operatorname{dist}(x_n,\operatorname{Crit}(V))\to0;
	\end{equation}
	in particular, every accumulation point is fixed. If \(\operatorname{Crit}(V)\) is
	finite, each orbit converges to one of its points.

\label{thm:Morse-hyperbolic}
	Let \(0<h<1/\Lambda\). Each non-degenerate critical point \(p\) of \(V\)
	is a hyperbolic fixed point of \(\bar F_h\), and
	\begin{equation}
		\label{eq:index-equality}
		\dim W^u(p)=\operatorname{ind}_{\mathrm M}(p).
	\end{equation}
	Such a point is a sink exactly when it is a strict local minimum,
	a source exactly when it is a strict local maximum, and a saddle
	otherwise.

\label{thm:global-dynamics}
	\label{cor:almost-everywhere}
	Let \(0<h<1/\Lambda\) and suppose that \(V\) is Morse. Then every orbit
	of \(\bar F_h\) converges to a critical point, and almost every orbit
	converges to a local minimum. If there is a unique local minimum
	\(p_*\), then
	\begin{equation}
		\label{eq:full-measure-basin}
		\operatorname{Leb}\bigl(\mathbb T_P^N\setminus\mathcal B(p_*)\bigr)=0.
	\end{equation}

\label{thm:matrix-morse-smale}
	Let $K$ be symmetric, nonsingular and weakly diagonally dominant, and let
	\begin{equation}
		\label{eq:matrix-ms-range}
		0<h<\frac{1}{\lambda_{\max}(K)}.
	\end{equation}
	Then $G_{K,h}$ is a Morse--Smale diffeomorphism of $\mathbb T^N$ with
	nonwandering set $\{0,\pi\}^N$.  It has $\binom Nr$ fixed points of
	unstable dimension $r$, for $r=0,\ldots,N$, and a unique sink
	$(\pi,\ldots,\pi)$, whose basin has full Lebesgue measure. The interval
	\eqref{eq:matrix-ms-range} is optimal: for $h\ge1/\lambda_{\max}(K)$,
	$G_{K,h}$ is not a local diffeomorphism.

\label{lem:adjoint-transversality}
	Let $G$ be a $C^1$ diffeomorphism of $\mathbb T^N$, let $p,q$ be hyperbolic
	fixed points, and let $z_n=G^n(z_0)$ with
	$z_0\in W^u(p)\cap W^s(q)$.  Set $A_n=DG(z_n)$.
	The intersection at $z_0$ is transverse if and only if the only solution of
	\begin{equation}
		\label{eq:adjoint-criterion}
		\eta_n=A_n^T\eta_{n+1},\qquad n\in\mathbb Z,
		\qquad
		\eta_n\longrightarrow0\quad\text{as }n\to\pm\infty,
	\end{equation}
	is $\eta_n=0$ for all $n$.

\label{thm:weighted}
	Let $K$ be symmetric, nonsingular and weakly diagonally dominant, and
	suppose that
	\begin{equation}
		\label{eq:weighted-dominance}
		k_{ii}a_i\ge\sum_{j\ne i}|k_{ij}|a_j,\qquad i=1,\ldots,N.
	\end{equation}
	Put $\tilde\lambda=\lambda_{\max}(A^{1/2}KA^{1/2})$.  For
	$0<h<1/\tilde\lambda$, the map $G_{K,A,h}$ is a Morse--Smale
	diffeomorphism with the nonwandering set, unstable dimensions and
	full-measure sink basin of Theorem~\ref{thm:matrix-morse-smale}.

\label{thm:general-tree-factorisation}
	The edge differences $z=B^T\theta$ identify the common-phase quotient
	with $\mathbb T_P^N$.  In these coordinates the reduced potential is $V_T$, and
	the reduced map is
	\begin{equation}
		z\longmapsto z-hK_T\nabla V_T(z)\pmod P.
		\label{eq:general-tree-map}
	\end{equation}
	Its critical set is
	\begin{equation}
		\operatorname{Crit}(V_T)=\prod_{e\in\mathsf E_T}\operatorname{Crit}(\Phi_e).
		\label{eq:general-tree-critical}
	\end{equation}
	If every $\Phi_e$ is Morse, then $V_T$ is Morse, with
	\begin{equation}
		\operatorname{ind}_{\mathrm M}(z)
		=\#\{e\in\mathsf E_T:\Phi_e''(z_e)<0\}.
		\label{eq:general-tree-index}
	\end{equation}
	If, moreover, each $\Phi_e$ has a unique local minimum $m_e$ modulo $P$,
	then $m=(m_e)_{e\in\mathsf E_T}$ is the unique local and absolute minimum
	of $V_T$ and, for $0<h<1/\Lambda$, the unique sink of
	\eqref{eq:general-tree-map}, with a basin of full Lebesgue measure.

\label{thm:tree}
	For a positive-weight tree with sinusoidal law, the reduced potential
	\begin{equation}
		V_T(z)=\sum_{e\in\mathsf E_T}a_e\cos z_e,
		\qquad \operatorname{Crit}(V_T)=\{0,\pi\}^N,
		\label{eq:tree-edge-coordinates}
	\end{equation}
	is Morse.  A critical point with $r$ zero coordinates has index $r$, so
	there are $\binom Nr$ points of each index.  The unique minimum is the
	phase-opposition state
	\begin{equation}
		z_e=\pi\quad\text{for every edge }e,
		\label{eq:tree-opposition}
	\end{equation}
	which is the unique sink, with a basin of full measure, whenever
	\begin{equation}
		0<h<\frac1{\lambda_{\max}(L_a)}.
		\label{eq:tree-diffeo}
	\end{equation}

\label{thm:path}\label{thm:path-morse-smale}
	For every $N\ge1$, the reduced path map $G_{K_N,h}$ is a Morse--Smale
	diffeomorphism for
	\begin{equation}
		0<h<\frac{1}{2+2\cos(\pi/(N+1))};
		\label{eq:path-diffeo-range}
	\end{equation}
	in particular, $0<h\le1/4$ suffices for every path length.  Its fixed
	points are the $2^N$ critical points of Corollary~\ref{thm:tree};
	$(\pi,\ldots,\pi)$ is the unique sink, with a full-measure basin, and
	$(0,\ldots,0)$ is the unique source.

\label{cor:wpath}
	Consider the path on $N+1$ vertices with weights $a_1,\ldots,a_N>0$ and
	sinusoidal interaction, and set $a_0=a_{N+1}=0$.  If
	\begin{equation}
		\label{eq:concave}
		2a_i\ge a_{i-1}+a_{i+1},\qquad i=1,\ldots,N,
	\end{equation}
	then the reduced map is Morse--Smale for $0<h<1/\lambda_{\max}(L_a)$,
	and this interval is optimal.

\label{prop:tree-sign-obstruction}
	Let $T$ be a tree with unit weights.  Suppose that its edges admit signs
	$d_e\in\{-1,1\}$, including a negative sign, such that
	\begin{equation}
		\label{eq:tree-sign-condition}
		\sum_{e\ni v}d_e=1\qquad\text{at every vertex }v.
	\end{equation}
	Then, for every $0<h<1/\lambda_{\max}(B^TB)$, its reduced sinusoidal map
	has a non-transverse heteroclinic intersection, and so is not
	Morse--Smale.  If $r$ edges have negative signs, the tree has $4r+2$
	vertices, and the stable and unstable tangent spaces along this
	intersection coincide, with dimension $3r+1$ in the reduced space of
	dimension $4r+1$.

\label{prop:tree-nontransverse}
Consider the tree with two adjacent vertices of degree three, each joined
to two leaves, with unit weights and sinusoidal interaction.
For
\begin{equation}
\label{eq:tree-counterexample-range}
    0<h<\frac{2}{5+\sqrt{17}},
\end{equation}
its reduced map on $\mathbb T^5$ is a diffeomorphism with a non-transverse
heteroclinic intersection.

\label{thm:all-to-all}
	The intrinsic potential is
	\begin{equation}
		\mathcal V_{\mathrm{all}}(\theta)
		=\sum_{1\le i<j\le N+1}\cos(\theta_i-\theta_j)
		=\frac12|Z(\theta)|^2-\frac{N+1}{2}.
		\label{eq:all-potential-order}
	\end{equation}
	Its absolute minima are precisely the \emph{balanced} configurations,
	those with $Z(\theta)=0$, and their potential value is $-(N+1)/2$.
